import { AwsClient } from "aws4fetch"
import type { Env } from "./common"
import { CT } from "./common"

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url)
    const m = url.pathname.match(/^\/items\/([^/]+)\/audio$/)
    if (!m) return new Response("not found", { status: 404 })
    if (req.headers.get("x-api-key") !== env.API_KEY && url.searchParams.get("key") !== env.API_KEY) return new Response("unauthorized", { status: 401 })
    const ttl = Number(url.searchParams.get("ttl") ?? 3600)
    const key = `${m[1]}.ogg`
    const client = new AwsClient({ accessKeyId: env.R2_ACCESS_KEY_ID, secretAccessKey: env.R2_SECRET_ACCESS_KEY, service: "s3", region: "auto" })
    const target = new URL(`https://${env.BUCKET}.${env.ACCOUNT_ID}.r2.cloudflarestorage.com/${key}`)
    target.searchParams.set("X-Amz-Expires", String(ttl))
    target.searchParams.set("response-content-type", CT(key))
    const signed = await client.sign(new Request(target, { method: "GET" }), { aws: { signQuery: true } })
    return new Response(null, { status: 307, headers: { location: signed.url, "access-control-allow-origin": "*" } })
  },
}

